//fade-in

 app.directive(
            "fadeIn",
            function() {
                // I alter the DOM to add the fader image.
                function compile( element, attributes, transclude ) {
                    element.prepend( "<img class='fader' />" );
                    return( link );
                }
                // I bind the UI events to the $scope.
                function link( $scope, element, attributes ) {
                    var fader = element.find( "img.fader" );
                    var primary = element.find( "img.image" );
                    // Watch for changes in the source of the primary
                    // image. Whenever it changes, we want to show it
                    // fade into the new source.
                    $scope.$watch(
                        "vm.current.image.link",
                        function( newValue, oldValue ) {
                            // If the $watch() is initializing, ignore.
                            if ( newValue === oldValue ) {
                                return;
                            }
                            // If the fader is still fading out, don't
                            // bother changing the source of the fader;
                            // just let the previous image continue to
                            // fade out.
                            if ( isFading() ) {
                                return;
                            }
                            initFade( oldValue );
                        }
                    );
                    // I prepare the fader to show the previous image
                    // while fading out of view.
                    function initFade( fadeSource ) {
                        fader
                            .prop( "src", fadeSource )
                            .addClass( "show" )
                            .css("margin-left", $(".imagemain1").css("margin-left"))
                        ;
                        // Don't actually start the fade until the
                        // primary image has loaded the new source.
                        primary.one( "load", startFade );
                    }
                    // I determine if the fader is currently fading
                    // out of view (that is currently animated).
                    function isFading() {
                        return(
                            fader.hasClass( "show" ) ||
                            fader.hasClass( "fadeOut" )
                        );
                    }
                    // I start the fade-out process.
                    function startFade() {
                        // The .width() call is here to ensure that
                        // the browser repaints before applying the
                        // fade-out class (so as to make sure the
                        // opacity doesn't kick in immediately).
                        fader.width();
                        fader.addClass( "fadeOut" );
                        setTimeout( teardownFade, 250 );
                    }
                    // I clean up the fader after the fade-out has
                    // completed its animation.
                    function teardownFade() {
                        fader.removeClass( "show fadeOut" );
                    }
                }
                // Return the directive configuration.
                return({
                    compile: compile,
                    restrict: "A"
                });
            }
        );

// Invoice flight-times display (§5 FRONTEND_CHARGE_TYPES_AND_TIMES_GUIDE.md).
// Renders the flight window line + one charged line, branching on the API's
// flight_details.charge_basis — matching the invoice PDFs exactly.
// Usage: <flight-charge-times details="flight.flight_details"></flight-charge-times>
app.directive('flightChargeTimes', ['$filter', function($filter) {

    // Per-basis explanations — VERBATIM from recorded_times_footnote() in the
    // backend's api/v1/models/pdf.model.php. A member holding a PDF next to the
    // app must see the same words; do not edit these without changing the PDF.
    var EXPLAIN = {
        airborne_plus_allowance: 'You are charged airborne time (first takeoff to last landing) plus a taxi allowance, so your charged time may differ from your actual brakes off to brakes on. Airborne and logbook times are rounded to the nearest 5 minutes; recorded times are exact.',
        airborne_rounded: 'You are charged airborne time (first takeoff to last landing), rounded to the nearest 5 minutes. Flight and airborne times are rounded to the nearest 5 minutes; recorded times are exact.',
        brakes_rounded: 'You are charged brakes off to brakes on, rounded to the nearest 5 minutes. Recorded times are exact.',
        brakes_exact: 'You are charged your actual brakes off to brakes on time, to the minute. Flight times are shown for your logbook, rounded to the nearest 5 minutes; recorded times are exact.',
        flight_exact: 'You are charged from first takeoff to last landing, to the minute. Flight times are shown for your logbook, rounded to the nearest 5 minutes; recorded times are exact.',
        airborne_actual: 'You are charged your actual airborne time as recorded by the aircraft tracker (or first takeoff to last landing when no recording is available), to the minute. Flight times are shown for your logbook, rounded to the nearest 5 minutes; recorded times are exact.',
        tacho: "You are charged by the aircraft's tacho reading, not by clock time. Flight times are shown for your logbook, rounded to the nearest 5 minutes; recorded times are exact.",
        hobbs: "You are charged by the aircraft's hobbs reading, not by clock time. Flight times are shown for your logbook, rounded to the nearest 5 minutes; recorded times are exact.",
        _default: 'Logbook times are rounded to the nearest 5 minutes; all other times to the nearest minute.'
    };

    function rec(t) {
        if (!t || t === '00:00:00' || t === '00:00') { return null; }
        return t;
    }

    function hm(mins) {
        if (mins === null || isNaN(mins)) { return ''; }
        return Math.floor(mins / 60) + ':' + ('0' + (mins % 60)).slice(-2);
    }

    function hoursToHM(dec) {
        var h = parseFloat(dec);
        if (isNaN(h)) { return ''; }
        return hm(Math.round(h * 60));
    }

    function fmt(t) {
        return roundTimeToMinute(t); // datetime.js global
    }

    function build(d) {
        if (!d) { return null; }

        var basis = d.charge_basis;
        if (!basis) {
            // Pre-rollout payloads without charge_basis: presence of the TPC window is
            // the only safe inference; anything else gets the window with no charging claim.
            basis = d.tpc_brakes_off ? 'airborne_plus_allowance' : '';
        }

        var m = { window: null, line: null };

        var wf = rec(d.brakes_off_rounded);
        var wt = rec(d.brakes_on_rounded);
        if (wf || wt) {
            m.window = {
                label: (basis === 'airborne_plus_allowance') ? 'Logbook time:' : 'Flight Times:',
                from: wf ? fmt(wf) : '–',
                to: wt ? fmt(wt) : '–'
            };
        }

        var takeoff = rec(d.takeoff_time), landing = rec(d.landing_time);
        var takeoffR = rec(d.takeoff_rounded), landingR = rec(d.landing_rounded);
        var line = null;

        if (basis === 'airborne_plus_allowance') {
            var charged = minutesBetween(d.tpc_brakes_off, d.tpc_brakes_on);
            var airborne = minutesBetween(takeoffR, landingR);
            if (takeoffR && landingR && charged !== null && airborne !== null) {
                line = {
                    pre: 'Charged: airborne ' + fmt(takeoffR) + ' - ' + fmt(landingR) +
                         ' (' + hm(airborne) + ') + ' + (charged - airborne) + ' min taxi allowance = ',
                    bold: hm(charged)
                };
            } else if (charged !== null) {
                // arithmetic can't be computed — plain charged window only
                line = { pre: 'Charged time: ' + fmt(d.tpc_brakes_off) + ' - ' + fmt(d.tpc_brakes_on), bold: '' };
            }

        } else if (basis === 'airborne_rounded') {
            var ab = minutesBetween(takeoffR, landingR);
            if (takeoffR && landingR && ab !== null) {
                line = { pre: 'Charged: airborne ' + fmt(takeoffR) + ' - ' + fmt(landingR) + ' (' + hm(ab) + ')', bold: '' };
            }

        } else if (basis === 'brakes_rounded') {
            var br = minutesBetween(wf, wt);
            if (br !== null) {
                // the span IS the flight-times window — don't repeat the clock times
                line = { pre: 'Charged: brakes off to brakes on (' + hm(br) + ')', bold: '' };
            }

        } else if (basis === 'brakes_exact') {
            var bo = rec(d.brakes_off), bn = rec(d.brakes_on);
            var be = minutesBetween(bo, bn);
            if (bo && bn && be !== null) {
                line = { pre: 'Charged: brakes off to brakes on ' + fmt(bo) + ' - ' + fmt(bn) + ' (' + hm(be) + ')', bold: '' };
            }

        } else if (basis === 'flight_exact') {
            var fe = minutesBetween(takeoff, landing);
            if (takeoff && landing && fe !== null) {
                line = { pre: 'Charged: takeoff to landing ' + fmt(takeoff) + ' - ' + fmt(landing) + ' (' + hm(fe) + ')', bold: '' };
            }

        } else if (basis === 'airborne_actual') {
            var at = parseFloat(d.airborne_time);
            if (!isNaN(at) && at > 0) {
                line = { pre: 'Charged: airborne time as recorded (' + hoursToHM(at) + ')', bold: '' };
            } else {
                var aa = minutesBetween(takeoff, landing);
                if (takeoff && landing && aa !== null) {
                    line = { pre: 'Charged: airborne (takeoff to landing) ' + fmt(takeoff) + ' - ' + fmt(landing) + ' (' + hm(aa) + ')', bold: '' };
                }
            }

        } else if (basis === 'tacho' || basis === 'hobbs') {
            // tacho_start / tacho_end are the only field names (hobbs uses the same pair)
            var ts = parseFloat(d.tacho_start);
            var te = parseFloat(d.tacho_end);
            if (!isNaN(ts) && !isNaN(te) && te > ts) {
                line = {
                    pre: 'Charged: ' + basis + ' ' + ts.toFixed(2) + ' - ' + te.toFixed(2) + ' (' + (te - ts).toFixed(2) + ' hours)',
                    bold: ''
                };
            }
        }
        // unknown/missing basis: window only, no charging claim

        // Tooltip = the PDF footnote text: "Recorded times: <list>. <explanation>"
        var recorded = $filter('recordedTimes')(d);
        var footnote = (recorded ? 'Recorded times: ' + recorded + '. ' : '') +
                       (EXPLAIN[basis] || EXPLAIN._default);
        if (m.window) { m.window.tooltip = footnote; }
        if (line) { line.tooltip = footnote; m.line = line; }

        return (m.window || m.line) ? m : null;
    }

    return {
        restrict: 'E',
        scope: { details: '=' },
        template:
            '<span class="fct">' +
              '<span ng-if="m.window" uib-tooltip="{{ m.window.tooltip }}">{{ m.window.label }} {{ m.window.from }} - {{ m.window.to }}</span>' +
              '<br ng-if="m.window && m.line" />' +
              '<span ng-if="m.line" uib-tooltip="{{ m.line.tooltip }}">{{ m.line.pre }}<strong ng-if="m.line.bold">{{ m.line.bold }}</strong></span>' +
            '</span>',
        link: function(scope) {
            scope.$watch('details', function(d) {
                scope.m = build(d);
            });
        }
    };
}]);

// ─────────────────────────────────────────────────────
// flightHeightProfile — altitude vs. elapsed-time chart for a flight replay,
// drawn with Chart.js (already loaded via CDN in index.html). Plots the
// backend's recommended altitude (baro when good, else GPS) filled under the
// curve, with a moving vertical cursor synced to the scrubber. Clicking the
// chart seeks (calls on-seek with the nearest index).
//
//   <flight-height-profile track="vm.track" current-index="vm.currentIndex"
//                          on-seek="vm.seekToIndex(i)"></flight-height-profile>
// ─────────────────────────────────────────────────────
app.directive('flightHeightProfile', ['$window', '$timeout', function ($window, $timeout) {
    return {
        restrict: 'E',
        scope: { track: '=', currentIndex: '=', onSeek: '&' },
        template: '<canvas class="fr-profile__canvas"></canvas>',
        link: function (scope, element) {

            var canvas = element[0].querySelector('canvas');
            var chart = null;

            // Chart.js plugin: draw a vertical cursor at the current index.
            var cursorPlugin = {
                id: 'frCursor',
                afterDatasetsDraw: function (c) {
                    var idx = scope.currentIndex || 0;
                    var meta = c.getDatasetMeta(0);
                    if (!meta || !meta.data || !meta.data[idx]) return;
                    var x = meta.data[idx].x;
                    var ctx = c.ctx, top = c.chartArea.top, bot = c.chartArea.bottom;
                    ctx.save();
                    ctx.beginPath();
                    ctx.moveTo(x, top); ctx.lineTo(x, bot);
                    ctx.lineWidth = 2;
                    ctx.strokeStyle = '#1e3a5f';
                    ctx.stroke();
                    ctx.beginPath();
                    ctx.arc(x, meta.data[idx].y, 4, 0, Math.PI * 2);
                    ctx.fillStyle = '#1e3a5f';
                    ctx.strokeStyle = '#fff';
                    ctx.lineWidth = 2;
                    ctx.fill(); ctx.stroke();
                    ctx.restore();
                }
            };

            function altOf(p) {
                var a = p.alt_recommended_ft;
                if (a == null) a = p.alt_ft;
                return a || 0;
            }

            function build() {
                if (!scope.track || !scope.track.length || !$window.Chart) return;

                var labels = scope.track.map(function (p) {
                    var s = p.elapsed_s || 0;
                    var m = Math.floor(s / 60);
                    return m + ':' + (('0' + Math.round(s % 60)).slice(-2));
                });
                var data = scope.track.map(altOf);

                var ctx = canvas.getContext('2d');
                var grad = ctx.createLinearGradient(0, 0, 0, 220);
                grad.addColorStop(0, 'rgba(45, 90, 142, 0.35)');
                grad.addColorStop(1, 'rgba(45, 90, 142, 0.02)');

                chart = new $window.Chart(ctx, {
                    type: 'line',
                    data: {
                        labels: labels,
                        datasets: [{
                            data: data,
                            borderColor: '#2d5a8e',
                            backgroundColor: grad,
                            borderWidth: 2,
                            fill: true,
                            pointRadius: 0,
                            tension: 0.25
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        animation: false,
                        interaction: { intersect: false, mode: 'index' },
                        plugins: {
                            legend: { display: false },
                            tooltip: {
                                displayColors: false,
                                callbacks: {
                                    title: function (items) { return 'T+' + items[0].label; },
                                    label: function (item) { return Math.round(item.parsed.y) + ' ft'; }
                                }
                            }
                        },
                        scales: {
                            x: { grid: { display: false }, ticks: { maxTicksLimit: 8, color: '#94a3b8', font: { size: 10 } } },
                            y: { grid: { color: '#eef2f7' }, ticks: { color: '#94a3b8', font: { size: 10 }, callback: function (v) { return v + ' ft'; } } }
                        },
                        onClick: function (evt, els, c) {
                            var pts = c.getElementsAtEventForMode(evt, 'index', { intersect: false }, false);
                            if (pts && pts.length) {
                                var i = pts[0].index;
                                scope.$applyAsync(function () { scope.onSeek({ i: i }); });
                            }
                        }
                    },
                    plugins: [cursorPlugin]
                });
            }

            // Build once the track arrives (after the controller's load()).
            var un = scope.$watch('track', function (t) {
                if (t && t.length && !chart) { $timeout(build); }
            });

            // Redraw the cursor as the scrubber moves.
            scope.$watch('currentIndex', function () { if (chart) chart.draw(); });

            // The container height changes when entering/leaving fullscreen.
            // Chart.js's ResizeObserver usually catches this, but force a resize
            // after the CSS transition so the canvas buffer matches its new box
            // (otherwise the labels can look squashed/stretched).
            scope.$on('fr-profile-resize', function () {
                if (!chart) return;
                $timeout(function () { chart.resize(); }, 80);
            });

            scope.$on('$destroy', function () {
                un();
                if (chart) { chart.destroy(); chart = null; }
            });
        }
    };
}]);

// ─────────────────────────────────────────────────────
// flightSixPack — the six classic flight instruments (plus extra readouts)
// driven by the currently-scrubbed track point of a flight replay.
//
//   <flight-six-pack point="vm.currentPoint" phase="vm.currentPoint.phase">
//
// `point` is one element of the replay `track[]` array (see
// FRONTEND_FLIGHT_REPLAY_GUIDE.md §2.2). All series are backend-derived — this
// directive only renders. Needles are SVG with CSS transitions so values tween
// smoothly between fixes (the controller can also rAF-interpolate `point`).
//
// Gauges: ASI (GS), Attitude (est.), Altimeter, Heading (DI), Turn coordinator,
// VSI. Below: G, OAT, satellites, phase.
// ─────────────────────────────────────────────────────
app.directive('flightSixPack', ['$sce', function ($sce) {
    return {
        restrict: 'E',
        scope: { point: '=' },
        templateUrl: 'js/directives/flightSixPack.html',
        link: function (scope) {

            // ── Helpers exposed to the template ──
            scope.num = function (v, dp) {
                if (v === null || v === undefined || isNaN(v)) return '–';
                return Number(v).toFixed(dp == null ? 0 : dp);
            };

            // ASI: map ground speed (kt) to a needle angle. Dial spans 0..160kt
            // over 270° (−135° at 0, +135° at full scale), clamped.
            scope.asiAngle = function () {
                var kt = (scope.point && scope.point.speed_kt) || 0;
                var frac = Math.max(0, Math.min(1, kt / 160));
                return -135 + frac * 270;
            };

            // Altimeter: hundreds-foot needle (one sweep per 1000 ft).
            scope.altHundredsAngle = function () {
                var ft = (scope.point && altFt()) || 0;
                return (ft % 1000) / 1000 * 360;
            };
            // thousands-foot needle (one sweep per 10 000 ft).
            scope.altThousandsAngle = function () {
                var ft = (scope.point && altFt()) || 0;
                return (ft % 10000) / 10000 * 360;
            };

            function altFt() {
                if (!scope.point) return 0;
                // Use the backend's recommended altitude (baro when good, else GPS).
                var v = scope.point.alt_recommended_ft;
                if (v === null || v === undefined) v = scope.point.alt_ft;
                return v || 0;
            }
            scope.altFt = altFt;

            // Heading indicator: rotate the compass card so current heading is up.
            scope.diCardAngle = function () {
                return -((scope.point && scope.point.heading) || 0);
            };

            // Attitude indicator.
            // Bank: the attitude sphere rotates OPPOSITE the aircraft's roll (the
            // aircraft symbol is fixed; the world tilts the other way). A right
            // bank (+deg) must make the sphere rotate counter-clockwise so the
            // ground rises on the right as the pilot sees it — i.e. a NEGATIVE
            // SVG angle (SVG rotate is clockwise-positive). So negate.
            scope.aiRoll = function () { return -((scope.point && scope.point.bank_est_deg) || 0); };
            // Pitch: shift the horizon DOWN for nose-up (more sky shown).
            // ~1.4 px per degree, clamped so the horizon stays within the dial.
            scope.aiPitchShift = function () {
                var p = (scope.point && scope.point.pitch_est_deg) || 0;
                return Math.max(-34, Math.min(34, p * 1.4));
            };

            // Turn coordinator: standard rate (3°/s) puts the wing on the index.
            // Map turn rate to a bank-style angle, clamped to ±20° on the dial.
            scope.tcAngle = function () {
                var dps = (scope.point && scope.point.turn_rate_dps) || 0;
                var a = (dps / 3) * 15;   // 3°/s → 15° tilt
                return Math.max(-25, Math.min(25, a));
            };

            // VSI: needle rests pointing LEFT (9 o'clock = 0 fpm), ±2000 fpm over
            // ±150°. The needle points left, so rotating it CLOCKWISE (positive
            // SVG angle) swings the tip UP toward the "UP" mark. Climb (positive
            // fpm) → positive angle; descent → negative (needle swings down).
            scope.vsiAngle = function () {
                var fpm = (scope.point && scope.point.vspeed_fpm) || 0;
                var frac = Math.max(-1, Math.min(1, fpm / 2000));
                return frac * 150;
            };

            // Phase pill class
            scope.phaseClass = function () {
                var p = (scope.point && scope.point.phase) || 'parked';
                return 'fr-phase--' + p;
            };
        }
    };
}]);

// ─────────────────────────────────────────────────────────────────────────
// flightWeatherPanel — stored METAR/TAF snapshots for a completed flight
// (FRONTEND_FLIGHT_WEATHER_GUIDE.md). One shared component, mounted from the
// personal logbook, journey logbooks, flight replay and the training-record
// flight popup:
//
//   <flight-weather-panel flight-id="e.ref_id"
//                         dep-name="vm.flight.departure_airport"    (optional)
//                         arr-name="vm.flight.destination_airport"> (optional)
//
// `flight-id` is always a plane_log_sheets.id. The directive fetches via
// FlightWeatherService (cached per flight — rows are immutable once stored),
// so it is lazy by construction: mount it behind an ng-if and the request
// only fires when the drawer/popup opens. All datetimes from the API are UTC
// strings — rendered with a Z suffix, never timezone-shifted.
//
// Companion: <wx-chip row="row"> — tiny category pill + wind summary reusing
// the same row shape (logbook rows / booking lists).
// ─────────────────────────────────────────────────────────────────────────
app.directive('flightWeatherPanel', ['FlightWeatherService', 'ToastService', '$timeout', function (FlightWeatherService, ToastService, $timeout) {
    return {
        restrict: 'E',
        scope: {
            flightId: '=',
            depName:  '=?',   // display name for the departure airfield (else the ICAO code)
            arrName:  '=?'    // display name for the arrival airfield
        },
        templateUrl: 'js/directives/flightWeatherPanel.html',
        link: function (scope) {

            scope.state = 'loading';   // loading | error | empty | ready
            scope.phases = [];

            var reducedMotion = window.matchMedia &&
                window.matchMedia('(prefers-reduced-motion: reduce)').matches;

            // ── UTC string helpers ("YYYY-MM-DD HH:MM:SS", never shifted) ──

            function parseUTC(s) {
                if (!s) { return null; }
                var m = String(s).split(/[^0-9]/);
                if (m.length < 5) { return null; }
                return Date.UTC(+m[0], +m[1] - 1, +m[2], +m[3], +m[4], +(m[5] || 0));
            }

            scope.fmtZ = function (s) {                       // "12:23Z"
                return s ? String(s).substr(11, 5) + 'Z' : '';
            };

            scope.fmtDayZ = function (s) {                    // "11/12Z"
                return s ? String(s).substr(8, 2) + '/' + String(s).substr(11, 2) + 'Z' : '';
            };

            function fmtUnixDayZ(sec) {                       // unix seconds → "11/12Z"
                if (!sec) { return ''; }
                var d = new Date(sec * 1000);
                return pad2(d.getUTCDate()) + '/' + pad2(d.getUTCHours()) + 'Z';
            }

            function pad2(n) { return (n < 10 ? '0' : '') + n; }

            // ── Load ──

            scope.load = function (force) {
                if (!scope.flightId) { return; }
                scope.state = 'loading';
                FlightWeatherService.GetForFlight(scope.flightId, force).then(function (data) {
                    if (!data || data.success === false) {
                        scope.state = 'error';
                        return;
                    }
                    buildPhases(data);
                });
            };

            scope.$watch('flightId', function (id) {
                if (id) { scope.load(false); }
            });

            // ── Model building ──

            function buildPhases(data) {
                var phases = [];
                addPhase(phases, 'takeoff', 'Departure', 'takeoff', data.takeoff, scope.depName);
                addPhase(phases, 'landing', 'Arrival', 'landing', data.landing, scope.arrName);

                if (!phases.length) {
                    scope.state = 'empty';
                    return;
                }
                scope.phases = phases;
                scope.state = 'ready';

                // Wind needles: start at north, then swing to the true direction
                // once the entry animation has landed (CSS transition tweens it).
                $timeout(function () {
                    angular.forEach(phases, function (phase) {
                        angular.forEach(phase.okRows, function (row) {
                            row._angle = windAngle(row);
                        });
                    });
                }, reducedMotion ? 0 : 350);
            }

            // An empty phase array = no usable time for that phase → hide it.
            function addPhase(phases, key, label, word, rows, givenName) {
                rows = rows || [];
                if (!rows.length) { return; }

                rows.sort(function (a, b) { return (a.station_rank || 0) - (b.station_rank || 0); });
                var okRows = rows.filter(function (r) { return r.status === 'ok'; });
                var first = rows[0];
                var code = first.airfield_code || '';

                var phase = {
                    key: key,
                    label: label,
                    word: word,
                    // Header shows "Name (CODE)" when a display name was passed
                    // in, else just the code.
                    placeName: givenName || code || 'Unknown airfield',
                    codeSuffix: (givenName && code && givenName !== code) ? code : '',
                    placeShort: givenName || code || 'the airfield',
                    timeZ: scope.fmtZ(first.requested_time),
                    rows: rows,
                    okRows: okRows,
                    active: 0,
                    activeRow: okRows.length ? [okRows[0]] : [],
                    emptyMsg: ''
                };

                if (!okRows.length) {
                    phase.emptyMsg = first.status === 'no_station'
                        ? 'No weather station near ' + phase.placeShort
                        : 'No weather report available near this time';
                }

                angular.forEach(okRows, function (row) {
                    row._raw = false;
                    row._angle = reducedMotion ? windAngle(row) : 0;
                    row._taf = buildTaf(row);
                    buildClouds(row);
                });

                phases.push(phase);
            }

            // ── Station toggle (recreates the report node → CSS cross-fade) ──

            scope.setStation = function (phase, idx) {
                if (phase.active === idx) { return; }
                phase.active = idx;
                phase.activeRow = [phase.okRows[idx]];
            };

            scope.stationLabel = function (row, phase) {
                if (row.is_exact_station) { return phase.placeName + (phase.codeSuffix ? ' (' + phase.codeSuffix + ')' : ''); }
                return row.station_icao;
            };

            // "observed 12:20Z — 3 min before takeoff"
            scope.deltaLabel = function (row, phase) {
                var req = parseUTC(row.requested_time);
                var obs = parseUTC(row.obs_time);
                if (req == null || obs == null) { return ''; }
                var mins = Math.round((req - obs) / 60000);
                if (mins === 0) { return 'at ' + phase.word; }
                return Math.abs(mins) + ' min ' + (mins > 0 ? 'before ' : 'after ') + phase.word;
            };

            // ── Decoded grid helpers (convenience columns only — no METAR parsing) ──

            scope.catClass = function (row) {
                var cat = (row.flight_category || '').toLowerCase();
                return { vfr: 'fw-cat--vfr', mvfr: 'fw-cat--mvfr', ifr: 'fw-cat--ifr', lifr: 'fw-cat--lifr' }[cat] || 'fw-cat--na';
            };

            scope.hasWind = function (row) {
                return row.wind_speed != null && row.wind_speed !== 0;
            };

            scope.windDirLabel = function (row) {
                if (row.wind_dir === 'VRB') { return 'VRB'; }
                return row.wind_dir != null ? row.wind_dir + '°' : '';
            };

            function windAngle(row) {
                var v = parseFloat(row.wind_dir);
                return isNaN(v) ? 0 : v;
            }

            scope.needleStyle = function (row) {
                return {
                    transform: 'rotate(' + (row._angle || 0) + 'deg)',
                    '-webkit-transform': 'rotate(' + (row._angle || 0) + 'deg)'
                };
            };

            // ── Cloud base (UK term; "ceiling" in the API) ──
            // Every reported layer from metar_json.clouds[] with the amount
            // spelled out (Few / Scattered / Broken / Overcast…), lowest first;
            // the layer that constitutes the cloud base (lowest BKN/OVC/VV) is
            // emphasised. Falls back to the flattened ceiling_ft column when
            // the JSON carries no layers.

            var COVER_LABELS = {
                FEW: 'Few', SCT: 'Scattered', BKN: 'Broken', OVC: 'Overcast',
                VV: 'Sky obscured', NSC: 'No significant cloud',
                NCD: 'No cloud detected', SKC: 'Sky clear', CLR: 'Sky clear',
                CAVOK: 'CAVOK'
            };

            function coverLabel(cover) {
                cover = String(cover || '').toUpperCase();
                return COVER_LABELS[cover] || cover;
            }

            function groupNum(n) {
                return String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
            }

            function buildClouds(row) {
                var layers = [];
                angular.forEach((row.metar_json && row.metar_json.clouds) || [], function (c) {
                    if (!c || !c.cover) { return; }
                    var cover = String(c.cover).toUpperCase();
                    var base = (c.base != null && isFinite(c.base)) ? Number(c.base) : null;
                    layers.push({
                        code: cover,
                        label: coverLabel(cover),
                        base: base,
                        baseLabel: base != null ? groupNum(base) : '',
                        isCeiling: false
                    });
                });
                layers.sort(function (a, b) {
                    if (a.base == null) { return 1; }
                    if (b.base == null) { return -1; }
                    return a.base - b.base;
                });
                // the cloud base = lowest broken/overcast/obscured layer
                for (var i = 0; i < layers.length; i++) {
                    if (/^(BKN|OVC|VV)$/.test(layers[i].code) && layers[i].base != null) {
                        layers[i].isCeiling = true;
                        break;
                    }
                }

                var note = '';
                if (!layers.length) {
                    if (row.ceiling_ft) {
                        layers.push({ code: '', label: 'Cloud base', base: Number(row.ceiling_ft),
                                      baseLabel: groupNum(row.ceiling_ft), isCeiling: true });
                    } else if (/CAVOK/i.test(row.raw_metar || '') || /CAVOK/i.test(row.visibility || '')) {
                        note = 'CAVOK';
                    } else {
                        note = 'No cloud reported';
                    }
                }
                row._clouds = layers;
                row._cloudsNote = note;
            }

            // ── Visibility ──────────────────────────────────────────────
            // Europe (incl. the UK) reports visibility in METRES/kilometres,
            // never statute miles. NOAA normalises every station it serves to
            // SM, so a UK field's "9999" comes back as "6+" — correct in the
            // wrong unit, and not what a European pilot reads off a METAR.
            //
            // The raw METAR is authoritative and already carries the original
            // group, so for European stations we take the visibility straight
            // out of it rather than back-converting NOAA's rounded SM value
            // (6+ SM → "9.7 km" would be both wrong and falsely precise).
            //
            // ICAO prefixes: the E* block (northern/western Europe, EG = UK)
            // and the L* block (southern Europe + the Mediterranean). A couple
            // of L* members sit outside Europe proper (LL Israel, LT Turkey)
            // but they report in metres too, so the unit is right regardless.
            function isEuropeanStation(icao) {
                return /^[EL][A-Z]/i.test(String(icao || ''));
            }

            // The visibility group in a METAR sits after the wind group and is
            // either 4 digits ("9999", "0350"), 4 digits + a direction for the
            // minimum-visibility variant ("2000NE"), or "CAVOK". Distances of
            // 10 km or more are always encoded 9999.
            function metresFromRawMetar(raw) {
                if (!raw) { return null; }
                var text = String(raw).toUpperCase();
                if (/\bCAVOK\b/.test(text)) { return 'CAVOK'; }
                // Anchor on the wind group so pressure/temperature digits can't
                // be mistaken for visibility.
                var m = text.match(/\b(?:\d{3}|VRB)\d{2}(?:G\d{2,3})?(?:KT|MPS|KMH)\s+(\d{4})(?:[NSEW]{1,2})?\b/);
                if (!m) { return null; }
                var metres = parseInt(m[1], 10);
                return isNaN(metres) ? null : metres;
            }

            // 9999 = "10 km or more". Below 5000 m METARs are read in metres;
            // at and above that, kilometres are the natural unit.
            function formatMetres(metres) {
                if (metres >= 9999) { return '10 km+'; }
                if (metres >= 5000) {
                    var km = metres / 1000;
                    return (km % 1 === 0 ? km : km.toFixed(1)) + ' km';
                }
                return groupNum(metres) + ' m';
            }

            // Values reached by converting a rounded SM figure carry no
            // metre-level accuracy — "1 1/2SM" is not 2,414 m of real
            // precision. METARs step visibility in 50 m up to 800 m and
            // 100 m beyond, so snap to that and don't imply more than we know.
            function snapMetres(metres) {
                if (metres >= 9999) { return 9999; }
                var step = metres < 800 ? 50 : 100;
                return Math.round(metres / step) * step;
            }

            scope.visLabel = function (row) {
                var v = row.visibility;
                var european = isEuropeanStation(row.station_icao);

                if (european) {
                    var fromRaw = metresFromRawMetar(row.raw_metar);
                    if (fromRaw === 'CAVOK') { return 'CAVOK'; }
                    if (fromRaw != null) { return formatMetres(fromRaw); }
                }

                if (v == null || v === '') { return '–'; }
                v = String(v);

                // Archive (iem) rows are already metres — a bare number there
                // needs formatting, not a unit suffix bolted on.
                if (row.source === 'iem' && /^\d+$/.test(v)) {
                    return formatMetres(parseInt(v, 10));
                }

                // A European station whose raw METAR we couldn't parse: the
                // only value we have is NOAA's SM. Convert rather than print a
                // unit European pilots don't use. "6+" means "10 km or more"
                // upstream, so it maps back to the 9999 wording exactly.
                if (european) {
                    if (/^\s*6\s*\+\s*$/.test(v)) { return '10 km+'; }
                    var sm = parseSM(v);
                    if (sm != null) { return formatMetres(snapMetres(sm * 1609.344)); }
                }

                if (/[a-zA-Z]/.test(v)) { return v; }
                return v + (row.source === 'iem' ? ' m' : ' SM');
            };

            // TAF period visibility. Unlike the METAR case there is no single
            // raw group to read — each period carries its own — so the decoded
            // value is converted. NOAA emits SM here too; a bare 4-digit value
            // is already the original metric group (9999 = 10 km or more).
            function tafVisLabel(visib, row) {
                var v = String(visib).trim();
                if (!isEuropeanStation(row && row.station_icao)) { return v; }
                if (/CAVOK/i.test(v)) { return 'CAVOK'; }
                if (/^\d{4}$/.test(v)) { return formatMetres(parseInt(v, 10)); }
                if (/^\s*6\s*\+\s*$/.test(v)) { return '10 km+'; }
                var sm = parseSM(v);
                if (sm != null) { return formatMetres(snapMetres(sm * 1609.344)); }
                return v;
            }

            // "1 1/2", "1/2", "2.5" → number of statute miles.
            function parseSM(v) {
                var text = String(v).replace(/SM/ig, '').trim();
                var m = text.match(/^(\d+)\s+(\d+)\/(\d+)$/);   // mixed: 1 1/2
                if (m) { return parseInt(m[1], 10) + parseInt(m[2], 10) / parseInt(m[3], 10); }
                m = text.match(/^(\d+)\/(\d+)$/);                // fraction: 1/2
                if (m) { return parseInt(m[1], 10) / parseInt(m[2], 10); }
                m = text.match(/^(\d+(?:\.\d+)?)$/);             // plain: 2 or 2.5
                if (m) { return parseFloat(m[1]); }
                return null;
            }

            // ── Raw text copy ──

            scope.copyRaw = function (text) {
                if (!text) { return; }
                if (navigator.clipboard && navigator.clipboard.writeText) {
                    navigator.clipboard.writeText(text).then(function () {
                        ToastService.success('Copied', 'Raw report copied to clipboard');
                    });
                } else {
                    var ta = document.createElement('textarea');
                    ta.value = text;
                    document.body.appendChild(ta);
                    ta.select();
                    document.execCommand('copy');
                    document.body.removeChild(ta);
                    ToastService.success('Copied', 'Raw report copied to clipboard');
                }
            };

            // ── TAF timeline ──
            // taf_json.fcsts[] = decoded periods (timeFrom/timeTo unix seconds,
            // fcstChange = FM/BECMG/TEMPO/PROB…). Base periods form the lane;
            // TEMPO/PROB/INTER render as an overlay stripe on top.

            function buildTaf(row) {
                var json = row.taf_json;
                var fcsts = json && json.fcsts;
                if (!row.raw_taf || !fcsts || !fcsts.length) { return null; }

                var from = parseUTC(row.taf_valid_from);
                var to = parseUTC(row.taf_valid_to);
                angular.forEach(fcsts, function (f) {
                    if (f.timeFrom) { from = Math.min(from == null ? f.timeFrom * 1000 : from, f.timeFrom * 1000); }
                    if (f.timeTo)   { to   = Math.max(to   == null ? f.timeTo   * 1000 : to,   f.timeTo   * 1000); }
                });
                if (from == null || to == null || to <= from) { return null; }

                var req = parseUTC(row.requested_time);
                var span = to - from;
                var pct = function (ms) { return Math.max(0, Math.min(100, (ms - from) / span * 100)); };

                var segments = [];
                var activeSeg = null;
                angular.forEach(fcsts, function (f, idx) {
                    var f0 = f.timeFrom ? f.timeFrom * 1000 : from;
                    var f1 = f.timeTo ? f.timeTo * 1000 : to;
                    if (f1 <= f0) { return; }
                    var change = (f.fcstChange || '').toUpperCase();
                    var tempo = /TEMPO|PROB|INTER/.test(change);
                    var seg = {
                        left: pct(f0),
                        width: Math.max(1.5, pct(f1) - pct(f0)),
                        label: change || (idx === 0 ? 'BASE' : 'FM'),
                        tempo: tempo,
                        timeLabel: fmtUnixDayZ(f0 / 1000) + ' → ' + fmtUnixDayZ(f1 / 1000),
                        active: false,
                        parts: describePeriod(f, row)
                    };
                    // The (base) period in force at the flight time gets the
                    // category highlight + is pre-selected.
                    if (!tempo && req != null && req >= f0 && req < f1) {
                        seg.active = true;
                        activeSeg = seg;
                    }
                    segments.push(seg);
                });
                if (!segments.length) { return null; }

                return {
                    segments: segments,
                    selected: activeSeg,
                    pinLeft: req != null ? pct(req) : 0
                };
            }

            // Human summary chips for one decoded TAF period. Field names follow
            // NOAA's parsed element (the iem parser emits the same subset) —
            // everything is optional, render only what's there.
            function describePeriod(f, row) {
                var parts = [];
                if (f.probability) { parts.push('PROB' + f.probability); }
                if (f.wdir != null || f.wspd != null) {
                    var w = (f.wdir === 'VRB' ? 'VRB' : (f.wdir != null ? f.wdir + '°' : '')) +
                            (f.wspd != null ? ' ' + f.wspd + ' kt' : '') +
                            (f.wgst ? ' G ' + f.wgst : '');
                    if (w.trim()) { parts.push('Wind ' + w.trim()); }
                }
                if (f.visib != null && f.visib !== '') { parts.push('Vis ' + tafVisLabel(f.visib, row)); }
                if (f.wxString) { parts.push(f.wxString); }
                angular.forEach(f.clouds || [], function (c) {
                    if (!c || !c.cover) { return; }
                    parts.push(coverLabel(c.cover) + (c.base != null ? ' ' + groupNum(c.base) + ' ft' : ''));
                });
                return parts;
            }

            scope.selectSeg = function (row, seg) {
                row._taf.selected = (row._taf.selected === seg) ? null : seg;
            };
        }
    };
}]);

// ── fwDrawerFit — size a weather drawer to its horizontal scrollport ──
// Used on the .fw-drawer wrapper when the panel lives inside a full-width
// <td colspan> of a horizontally-scrolling logbook table. A viewport-based
// max-width can exceed the scrollport, and then `position: sticky` runs out
// of travel and the drawer clips off-screen. This measures the real
// scrollport, caps the drawer to it, and scrolls the table back to the left
// so the drawer opens fully in view.
app.directive('fwDrawerFit', ['$timeout', function ($timeout) {
    return {
        restrict: 'A',
        link: function (scope, element) {
            var el = element[0];

            function scroller() {
                var node = el.parentElement;
                while (node && node !== document.body) {
                    var ox = window.getComputedStyle(node).overflowX;
                    if (ox === 'auto' || ox === 'scroll') { return node; }
                    node = node.parentElement;
                }
                return null;
            }

            function fit() {
                var sc = scroller();
                if (!sc) { return; }
                el.style.maxWidth = sc.clientWidth + 'px';
            }

            $timeout(function () {
                fit();
                var sc = scroller();
                if (sc && sc.scrollLeft > 0) {
                    if (sc.scrollTo) { sc.scrollTo({ left: 0, behavior: 'smooth' }); }
                    else { sc.scrollLeft = 0; }
                }
            });

            window.addEventListener('resize', fit);
            scope.$on('$destroy', function () {
                window.removeEventListener('resize', fit);
            });
        }
    };
}]);

// ── fwTicker — count a number up from 0 on first reveal (~400 ms) ──
// <span fw-ticker="row.wind_speed"></span>            → "11"
// <span fw-ticker="row.ceiling_ft" fw-ticker-group="true"></span> → "4,300"
// Values may be numeric strings ("29.0"); rendered rounded to integers like
// the rest of the grid. Respects prefers-reduced-motion (renders instantly).
app.directive('fwTicker', [function () {
    return {
        restrict: 'A',
        link: function (scope, element, attrs) {
            var reducedMotion = window.matchMedia &&
                window.matchMedia('(prefers-reduced-motion: reduce)').matches;
            var group = attrs.fwTickerGroup === 'true';

            function fmt(v) {
                var n = Math.round(v);
                if (!group) { return String(n); }
                return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
            }

            scope.$watch(attrs.fwTicker, function (val) {
                var target = parseFloat(val);
                if (isNaN(target)) { element.text('–'); return; }
                if (reducedMotion || !window.requestAnimationFrame) {
                    element.text(fmt(target));
                    return;
                }
                var start = null;
                var DURATION = 400;
                function step(ts) {
                    if (start === null) { start = ts; }
                    var t = Math.min(1, (ts - start) / DURATION);
                    var eased = 1 - Math.pow(1 - t, 3);   // ease-out cubic
                    element.text(fmt(target * eased));
                    if (t < 1) { window.requestAnimationFrame(step); }
                }
                window.requestAnimationFrame(step);
            });
        }
    };
}]);

